F_TRI=formula('μ(x)=max(0,min((x−a)/(b−a),(c−x)/(c−b)))',{'μ':'triangular membership grade','x':'input value','a,b,c':'ordered zero-left, peak and zero-right breakpoints'},{'μ':'dimensionless','x,a,b,c':'same input units'},['a<b<c; peak membership is 1.'])
F_TRAP=formula('μ(x)=max(0,min((x−a)/(b−a),1,(d−x)/(d−c)))',{'μ':'trapezoidal membership grade','x':'input value','a,b,c,d':'ordered left zero, plateau start, plateau end and right zero'},{'μ':'dimensionless','x,a,b,c,d':'same input units'},['a<b≤c<d; plateau membership is 1.'])
F_GAUSS=formula('μ(x)=exp(−(x−m)²/(2σ²))',{'μ':'unit-height Gaussian membership grade','x':'input value','m':'center of the membership function','σ':'positive width parameter'},{'μ':'dimensionless','x,m,σ':'same input units'},['σ>0; this is membership, not a probability density.'])
F_WEIGHT=formula('z*=Σ_i w_i z_i / Σ_i w_i',{'z*':'crisp output','w_i':'nonnegative activation weight of output singleton i','z_i':'representative output value of singleton i','i':'index over the active singleton outputs'},{'w_i':'dimensionless','z*,z_i':'same output units'},['Σ_i w_i>0; use the explicitly stated aggregation convention.'])
F_MAMDANI=formula('μ_out(z)=max_i min(α_i,μ_i(z)); z*=∫ z μ_out(z) dz / ∫ μ_out(z) dz',{'μ_out':'aggregated output membership function','μ_i':'unclipped consequent membership function of rule i','α_i':'firing strength of rule i','z':'output-coordinate variable','z*':'area-centroid crisp output','i':'index over fired rules'},{'μ_out,μ_i,α_i':'dimensionless','z,z*':'same output units'},['Minimum implication and maximum aggregation are chosen; integrals span the output universe; positive finite aggregated area.'])
